<script setup lang="ts">
import {computed,ref,watch,nextTick,useId} from 'vue'
import {VueFlow,Handle,Position,useVueFlow} from '@vue-flow/core'
import dagre from '@dagrejs/dagre'
import {clueForest,filterForest,descendants,branchSelection,toggleBranch,canReparent,type Branch} from './treeRuntime'
import '@vue-flow/core/dist/style.css'
import '@vue-flow/core/dist/theme-default.css'
const props=withDefaults(defineProps<{folders:any[],clues:any[],selected?:string,mode?:'manage'|'knowledge'|'pick',modelValue?:string[],eligible?:string[],reasons?:Record<string,string>,disabled?:boolean,moving?:string,moveNode?:(source:string,target:string)=>Promise<void>}>(),{mode:'manage',modelValue:()=>[],eligible:()=>[]})
const emit=defineEmits(['select','folder','destination','update:modelValue'])
const forest=computed(()=>clueForest(props.folders,props.clues)),query=ref(''),collapsed=ref<string[]>(props.folders.filter(f=>f.root).map(f=>'f:'+f.id)),expanded=ref(false),drop=ref(''),movingNow=ref(false),inspected=ref(''),nodes=ref<any[]>([]),edges=ref<any[]>([])
const graphId='clue-'+useId()
const {fitView,zoomIn,zoomOut}=useVueFlow(graphId)
const filtered=computed(()=>filterForest(forest.value,query.value))
const eligibleIds=computed(()=>props.eligible)
const selectedCount=computed(()=>props.modelValue.filter(id=>eligibleIds.value.includes(id)).length)
const all=computed(()=>{const a:Branch[]=[];function walk(n:Branch){a.push(n);n.children.forEach(walk)}forest.value.forEach(walk);return a})
function state(n:Branch){return branchSelection(all.value.find(v=>v.id===n.id)||n,props.modelValue,eligibleIds.value)}
function toggle(n:Branch){if(!props.disabled)emit('update:modelValue',toggleBranch(all.value.find(v=>v.id===n.id)||n,props.modelValue,eligibleIds.value))}
async function fold(n:Branch){collapsed.value=collapsed.value.includes(n.id)?collapsed.value.filter(id=>id!==n.id):[...collapsed.value,n.id];await nextTick();requestAnimationFrame(()=>fitView({nodes:[n.id,...descendants(n).map(v=>v.id)],padding:.15,minZoom:.65,maxZoom:1}))}
function count(n:Branch){return descendants(all.value.find(v=>v.id===n.id)||n).length}
function authenticity(n:Branch){const units=n.record?.draft?.units||[];return units.some((u:any)=>u.category==='fiction')?'fiction':units.some((u:any)=>u.category==='inference')?'inference':'supported'}
function choose(n:Branch){if(props.mode==='pick'){if(n.folder&&props.moving&&canReparent(forest.value,props.moving,n.id))emit('destination',n.id.slice(2));return}if(n.folder){fold(n)}else{inspected.value=n.id;emit('select',n.id.slice(2))}}
let first=true
function initialized(){if(first&&nodes.value.length){first=false;fitView({padding:.15,maxZoom:1})}}
async function layout(){
 const visible:Branch[]=[],links:any[]=[];function walk(n:Branch){visible.push(n);if(query.value||!collapsed.value.includes(n.id))for(const child of n.children){links.push({id:n.id+'>'+child.id,source:n.id,target:child.id,type:'smoothstep',style:{stroke:'#b2c5bd',strokeWidth:1.3},selectable:false});walk(child)}}filtered.value.forEach(walk)
 const g=new dagre.graphlib.Graph();g.setGraph({rankdir:'LR',nodesep:18,ranksep:60,marginx:24,marginy:24});g.setDefaultEdgeLabel(()=>({}));for(const n of visible)g.setNode(n.id,{width:n.folder?190:230,height:n.folder?76:102});for(const e of links)g.setEdge(e.source,e.target);dagre.layout(g)
 nodes.value=visible.map(n=>{const p=g.node(n.id);return {id:n.id,type:'card',position:{x:p.x-(n.folder?95:115),y:p.y-(n.folder?38:51)},data:{branch:n},draggable:props.mode==='manage'&&!n.root&&!n.synthetic&&!props.disabled,dragHandle:'.tree-drag',selectable:false}});edges.value=links

}
watch(()=>JSON.stringify([props.folders,props.clues.map(r=>[r.id,r.draft?.parentId,r.draft?.type]),query.value,collapsed.value]),layout,{immediate:true})
// Content edits update cards without moving the viewport or relaying out the tree.
watch(()=>props.clues,()=>{const current=new Map(all.value.map(n=>[n.id,n]));for(const node of nodes.value)if(current.has(node.id))node.data={branch:current.get(node.id)}},{deep:true})
function targetAt(event:any,source:string){const e=event.touches?.[0]||event;return Array.from(document.querySelectorAll<HTMLElement>('[data-tree-id]')).filter(el=>{const r=el.getBoundingClientRect();return e.clientX>=r.left&&e.clientX<=r.right&&e.clientY>=r.top&&e.clientY<=r.bottom&&canReparent(forest.value,source,el.dataset.treeId||'')}).map(el=>el.dataset.treeId!)[0]||''}
function dragging({event,node}:any){drop.value=targetAt(event,node.id)}
async function dropped({event,node}:any){const target=targetAt(event,node.id);drop.value='';if(target&&props.moveNode){movingNow.value=true;try{await props.moveNode(node.id,target)}finally{movingNow.value=false;layout()}}else layout()}
const detail=computed(()=>all.value.find(n=>n.id===inspected.value))
async function search(){await nextTick();fitView({padding:.15,maxZoom:1})}
async function enlarge(){expanded.value=!expanded.value;await nextTick();fitView({padding:.15,maxZoom:1})}
</script>
<template><section class="clue-map" :class="{enlarged:expanded}" :aria-label="mode==='knowledge'?'人物知识树':mode==='pick'?'选择目标分类':'线索层级树'"><header class="map-toolbar"><input v-model="query" type="search" placeholder="搜索分类或线索" aria-label="搜索分类或线索" @input="search"><span v-if="mode==='knowledge'" class="selection-count">已选 {{selectedCount}} / {{eligibleIds.length}}</span><button @click="collapsed=[]">展开全部</button><button @click="zoomOut()" aria-label="缩小线索树">−</button><button @click="zoomIn()" aria-label="放大线索树">＋</button><button @click="fitView({padding:.15,maxZoom:1})">适应视图</button><button @click="enlarge">{{expanded?'收起大图':'展开大图'}}</button></header><p class="map-hint">{{mode==='manage'?'点击线索编辑；拖动 ⋮⋮ 到同类分类可移动归属。':mode==='knowledge'?'勾选决定人物知晓的线索；分类勾选包含全部可选后代，不受搜索影响。':'点击目标分类完成移动；不符合条件的分类不可选择。'}}<span v-if="movingNow" role="status"> 正在保存移动…</span></p><div class="map-canvas"><VueFlow :id="graphId" :nodes="nodes" :edges="edges" :nodes-connectable="false" :edges-updatable="false" :min-zoom=".25" :max-zoom="1.8" :pan-on-drag="true" :zoom-on-scroll="false" :zoom-on-pinch="true" @nodes-initialized="initialized" @node-drag="dragging" @node-drag-stop="dropped"><template #node-card="{data}"><div :data-tree-id="data.branch.id" class="map-node" :class="[data.branch.type,authenticity(data.branch),{folder:data.branch.folder,chosen:selected===data.branch.id.slice(2),destination:drop===data.branch.id}]"><Handle type="target" :position="Position.Left" :connectable="false"/><div class="map-node-heading"><button v-if="mode==='manage'&&!data.branch.root&&!data.branch.synthetic" class="tree-drag" :disabled="disabled||movingNow" :aria-label="'拖动'+data.branch.name" title="拖动到分类">⋮⋮</button><input v-if="mode==='knowledge'" type="checkbox" :checked="state(data.branch).checked" :indeterminate.prop="state(data.branch).mixed" :aria-checked="state(data.branch).mixed?'mixed':state(data.branch).checked" :disabled="disabled||!state(data.branch).total" :aria-label="'知晓：'+data.branch.name" @change="toggle(data.branch)" class="nodrag"><button class="node-name nodrag" :disabled="mode==='pick'&&(!data.branch.folder||!moving||!canReparent(forest,moving,data.branch.id))" :aria-label="(data.branch.folder?'分类：':'线索：')+data.branch.name" @click="choose(data.branch)">{{data.branch.name}}</button><button v-if="data.branch.folder&&data.branch.children.length" class="fold nodrag" :aria-label="'展开或折叠'+data.branch.name" :aria-expanded="!!query||!collapsed.includes(data.branch.id)" @click="fold(data.branch)">{{!query&&collapsed.includes(data.branch.id)?'+':'−'}}</button></div><small v-if="data.branch.folder">{{mode==='knowledge'?state(data.branch).count+' / '+state(data.branch).total+' 已选':count(data.branch)+' 条线索'}}<button v-if="mode==='manage'&&!data.branch.synthetic" class="node-menu nodrag" :disabled="disabled" :aria-label="'管理分类'+data.branch.name" @click="emit('folder',data.branch)">管理</button></small><small v-else class="node-preview">{{mode==='knowledge'?(reasons?.[data.branch.id.slice(2)]||(!eligibleIds.includes(data.branch.id.slice(2))?'当前不可分配，请先补齐该线索':'可分配知识')):(data.branch.record?.draft?.summary||data.branch.record?.draft?.content||'点击查看内容与依据')}}</small><Handle v-if="data.branch.folder" type="source" :position="Position.Right" :connectable="false"/></div></template></VueFlow><div v-if="!nodes.length" class="map-empty">{{query?'没有匹配的分类或线索':'暂无线索，可先生成或新建。'}}</div></div><aside v-if="mode==='knowledge'&&detail" class="knowledge-preview"><b>{{detail.name}}</b><p>{{detail.record?.draft?.summary||detail.record?.draft?.content||'可在下方查看分配理由，在线索库编辑完整内容。'}}</p><small>{{reasons?.[detail.id.slice(2)]}}</small></aside></section></template>
<style>
.clue-map .vue-flow__node-card{pointer-events:all!important}
.clue-map{border:1px solid #dce5e0;border-radius:12px;overflow:hidden;background:#fafcfb;min-width:0}.clue-map.enlarged{position:fixed;inset:24px;z-index:60;box-shadow:0 0 0 60px #20362c66;display:flex;flex-direction:column}.map-toolbar{display:flex;gap:6px;align-items:center;padding:12px;flex-wrap:wrap;background:white;border-bottom:1px solid #e7ede9}.map-toolbar input{min-width:140px;flex:1;width:160px;margin:0!important;font-size:12px!important}.map-toolbar button{font-size:11px;padding:6px 9px}.selection-count{font-size:12px;color:#55776a}.map-hint{margin:0;padding:9px 13px;font-size:11px;color:#819187}.map-canvas{height:570px;position:relative}.enlarged .map-canvas{flex:1;height:auto;min-height:200px}.map-node{width:230px;height:102px;padding:13px 12px;border-radius:10px;border:1px solid #9cb6c4;background:#f5fafc;box-shadow:0 2px 7px #294b3710;box-sizing:border-box;color:#365c70}.map-node.relationship{background:#faf7fc;color:#795c8b;border-color:#baa8c6}.map-node.narrative{background:#f4faf6;color:#426e57;border-color:#a0bda9}.map-node.inference{border-style:dashed}.map-node.fiction:not(.folder){border-color:transparent}.map-node.folder{width:190px;height:76px;background:white;border:1px solid #cbd9d1;color:#4e6d5e}.map-node.chosen{box-shadow:0 0 0 2px #4f8a78}.map-node.destination{box-shadow:0 0 0 4px #6aaf84;background:#e7f7ec}.map-node-heading{display:flex;gap:5px;align-items:flex-start}.map-node button{border:0;background:transparent;color:inherit;margin:0;padding:0;border-radius:3px}.map-node .node-name{text-align:left;line-height:1.45;font-weight:600;font-size:13px;flex:1;display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow:hidden}.map-node .tree-drag{cursor:grab;touch-action:none;font-size:16px;color:#9aaea2;flex:none}.map-node .fold{width:20px;height:20px;background:#edf3ef;flex:none}.map-node input[type=checkbox]{flex:none;width:15px!important;height:15px;margin:2px 3px 0 0!important;accent-color:#458373}.map-node small{font-size:10px;display:block;margin-top:7px;color:#83958a;line-height:1.5}.map-node .node-menu{float:right;font-size:10px}.node-preview{display:-webkit-box!important;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow:hidden}.map-empty{position:absolute;inset:0;display:grid;place-items:center;color:#8c9b91;pointer-events:none;font-size:13px}.knowledge-preview{padding:14px;background:white;border-top:1px solid #e0e9e3;font-size:13px}.knowledge-preview p{white-space:pre-wrap}.map-node .vue-flow__handle{width:5px;height:5px;min-width:5px;min-height:5px;border:0;background:#a1b9ad}.clue-editor-layout{display:grid;grid-template-columns:minmax(0,1.7fr) minmax(290px,1fr);gap:20px;align-items:start}.clue-tree-area{min-width:0}.clue-tree-area .rail-heading{margin:0 0 12px}.clue-editor-layout>article{max-height:calc(100vh - 170px);overflow:auto}.tree-picker{width:min(1050px,95vw)!important;max-width:1050px!important}.tree-picker .map-canvas{height:450px}@media(max-width:1100px){.clue-editor-layout{grid-template-columns:1fr}.clue-editor-layout>article{max-height:none}.map-canvas{height:480px}}@media(max-width:600px){.map-canvas{height:400px}.clue-map.enlarged{inset:8px}.map-toolbar{padding:8px}}
</style>
